[
  {
    "statement": "No studies were found that evaluated the effects on peatland vegetation of changing the season or timing of livestock grazing.",
    "citations": [
      "1737"
    ]
  },
  {
    "statement": "One study on a bog in the UK found that lower grazing intensity resulted in greater total vegetation, shrub cover, and vegetation biomass.",
    "citations": [
      "1735"
    ]
  },
  {
    "statement": "A study found that excluding sheep from a bog in the UK led to an increase in total vegetation, shrub, and bryophyte biomass.",
    "citations": [
      "1734"
    ]
  },
  {
    "statement": "In one study, excluding sheep had no effect on the plant community in wetter areas of a bog.",
    "citations": [
      "1734"
    ]
  },
  {
    "statement": "In the same study, excluding sheep in drier areas of a bog favored dry moorland plants.",
    "citations": [
      "1734"
    ]
  },
  {
    "statement": "Five studies found that excluding livestock did not affect Sphagnum moss cover.",
    "citations": [
      "1734"
    ]
  }
]

[
  {
    "statement": "A study in a fen meadow in Poland found that excluding wild boar and deer had varying effects on vascular plant and moss cover, total vegetation biomass, and plant species richness, depending on other concurrent treatments.",
    "citations": [
      "1860"
    ]
  },
  {
    "statement": "No studies were found that assessed the effects of controlling wild herbivore populations on peatland vegetation.",
    "citations": [
      "1861"
    ]
  },
  {
    "statement": "No evidence was found regarding the effects of introducing beavers to impede water flow in forest watercourses.",
    "citations": [
      "1187"
    ]
  }
]

[
  {
    "statement": "A replicated, paired, controlled study in a bog in the UK found that burning increased cottongrass cover after 8-18 years.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "A study in a UK bog found that cottongrass cover was similar in plots burned every 10 or 20 years.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "Three replicated, paired studies in a bog in the UK found that heather cover was lower in plots burned more often.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "In a UK bog, moss cover, including Sphagnum, was higher in plots that were burned more often.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "One replicated, paired, controlled study in a bog in the UK found that plots burned more frequently contained more biomass of grass-like plants.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "One replicated, paired, controlled study in a bog in the UK found that plots burned more frequently contained less total vegetation, shrub and bryophyte biomass.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "One replicated, controlled study in a bog in the UK found that burning reduced or limited plant species richness.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "A replicated, controlled study in a bog in New Zealand found that burning increased plant species richness or diversity.",
    "citations": [
      "1763"
    ]
  }
]
